class Solution:
    def maxDistinctElements(self, nums: list[int], k: int) -> int:
        nums.sort()
        next_available = -float('inf')
        distinct_count = 0

        for num in nums:
            left = num - k
            right = num + k
            target = max(left, next_available)
            if target <= right:
                distinct_count += 1
                next_available = target + 1

        return distinct_count

class Solution {
public:
    int maxDistinctElements(vector<int>& nums, int k) {
        sort(nums.begin(), nums.end());
        long long nextAvailable = -2e18;
        int distinctCount = 0;

        for (int num : nums) {
            long long left = (long long)num - k;
            long long right = (long long)num + k;
            long long target = max(left, nextAvailable);
            if (target <= right) {
                distinctCount++;
                nextAvailable = target + 1;
            }
        }
        return distinctCount;
    }
};

class Solution {
    public int maxDistinctElements(int[] nums, int k) {
        Arrays.sort(nums);
        long nextAvailable = Long.MIN_VALUE;
        int distinctCount = 0;

        for (int num : nums) {
            long left = (long) num - k;
            long right = (long) num + k;
            long target = Math.max(left, nextAvailable);
            if (target <= right) {
                distinctCount++;
                nextAvailable = target + 1;
            }
        }
        return distinctCount;
    }
}

